('INT001', 'Dispute Charge', 0.95, 'Arvind charged voice on my ... happens this time.', 'Credit Card', 'Duplicate charge: System error', 'Initiated a chargeback request and flagged for refund.', 'pending', 'N/A', 'frustration, anger', 'Negative', 'Agent remained calm and professional despite customer''s frustration.', 8, 4, FALSE, NULL),
('INT002', 'Billing Dispute', 0.95, 'Hey, I''ve been charged ... happens this time.', 'Credit Card', 'Duplicate charge: System error', 'Initiated a chargeback request and promised updates.', 'resolved', 'Chargeback request initiated; refund expected in 5-7 business days.', 'frustration, anger, urgency', 'Negative', 'Agent remained calm and empathetic despite customer''s frustration.', 8, 6, FALSE, NULL),
('INT003', 'Login Issue', 0.95, 'Hi I can''t login to invalid credentials', 'Savings Account', 'Unable to login: Invalid credentials, OTP not received: OTP system delayed', 'Verified registered mobile number and manually reset access, sending a temporary password.', 'resolved', 'Agent manually reset the customer''s access and sent a temporary password.', 'frustration, annoyance', 'Negative', 'Professional and empathetic.', 9, 7, FALSE, NULL),
('INT004', 'EMI Increase Dispute', 0.95, 'Your banks cheating me ... I am not paying extra.', 'Loan', 'Unexpected EMI increase: Floating interest rate increase due to RBI''s repo rate hike.', 'Agent apologized, reviewed the account, explained the reason for the increase, offered to explain EMI calculation, escalated to supervisor, and offered EMI moratorium option.', 'pending', 'N/A', 'anger, frustration', 'Negative', 'Agent remained calm and professional despite customer''s anger.', 7, 2, FALSE, NULL),
('INT005', 'Request to speak to manager', 0.90, 'You should do want ... speak to your manager.', 'Loan', NULL, 'Agent agreed to escalate the issue to the supervisor.', 'pending', 'N/A', 'anger, frustration', 'Negative', 'Agent remained calm and professional despite customer''s anger.', 7, 2, FALSE, NULL),
('INT006', 'Debit Card Issue', 0.95, 'Hello, my debit card ... what''s the deal?', 'Debit Card', 'Debit card declined at store: Insufficient funds in the account.', 'Verified card activity, identified insufficient funds, and initiated fund transfer from savings.', 'resolved', 'Funds transferred from savings to cover transaction amount.', 'frustration, surprise', 'Neutral', 'Professional and helpful.', 9, 8, FALSE, NULL),
('INT007', 'Aadhaar Linking Assistance', 0.95, 'Hello, I want to know and submit online which', 'Savings Account, Aadhaar', 'Difficulty linking Aadhaar to savings account: Customer unable to get help at the branch and unfamiliar with online processes.', 'Offered to guide through the process, provided options to visit the branch or send a form via email.', 'resolved', 'Agent offered to send a form to the customer''s email for online submission.', 'frustration, apprehension, gratitude', 'Positive', 'Professional and helpful.', 9, 9, FALSE, NULL),
('INT008', 'Report Fraudulent Transaction', 0.95, 'I got a fraud ... identite make', 'Credit Card', 'Unauthorized transaction: Card compromised', 'Blocked the card, filed a fraud report, and issued a replacement card.', 'resolved', 'Card blocked, fraud report filed, replacement card issued.', 'worried, anxious', 'Negative', 'Professional and empathetic.', 9, 8, TRUE, 'In 7 to 10 days'),
('INT009', 'Inquire About Refund', 0.90, 'But what about ... get it back?', 'Credit Card', NULL, 'Initiated a chargeback request and promised to follow up.', 'pending', 'N/A', 'concerned, hopeful', 'Neutral', 'Helpful and reassuring.', 9, 8, TRUE, 'In 7 to 10 days'),
('INT010', 'UPI Setup Assistance', 0.95, 'How do I set ... with my phone.', 'Savings Account, Mobile App, UPI', NULL, 'The agent provided instructions on how to set up UPI.', 'resolved', 'The agent provided the steps to set up UPI.', 'curious, positive', 'Positive', 'The agent was helpful and polite.', 9, 9, FALSE, NULL),
('INT011', 'Request EMI Moratorium', 0.95, 'I am trying to get and your website so confusing', 'Home Loan', 'Website is confusing: N/A', 'Agent apologized, asked for loan account number, checked eligibility.', 'resolved', 'Agent confirmed eligibility for 3-month moratorium.', 'frustration, relief', 'Positive', 'Professional and helpful.', 9, 9, FALSE, NULL),
('INT012', 'Inquire about CIBIL score impact', 0.98, 'Yes, please, but will affect my CIBIL score?', 'Home Loan', NULL, 'Agent clarified moratorium won''t directly impact CIBIL score but interest will accrue.', 'resolved', 'Agent explained CIBIL impact and offered to send detailed email.', 'anxiety, relief', 'Positive', 'Professional and informative.', 10, 10, FALSE, NULL),
('INT013', 'Card Activation', 0.95, 'I''ve been trying to send it.', 'Credit Card', 'Card activation failed through automated process: Unknown processing error.', 'Verified customer details and manually activated the card.', 'resolved', 'Agent manually activated the customer''s credit card.', 'frustration, impatience', 'Negative', 'Agent remained professional despite customer''s impatience.', 9, 7, FALSE, NULL),
('INT014', 'Confirmation Request', 0.90, 'Would you like to send it.', 'Credit Card', NULL, 'Offered to send a confirmation of activation.', 'resolved', 'Agent will send a confirmation to the customer.', 'relief', 'Positive', 'Professional and helpful.', 10, 9, FALSE, NULL),
('INT015', 'Technical Support', 0.95, 'I can''t set up and everytime I try.', 'Mobile Banking App', 'Mobile banking app crashing: Unknown, possibly outdated app version or compatibility issue.', 'Suggested uninstalling and reinstalling the app.', 'pending', 'N/A', 'frustration, impatience', 'Negative', 'Agent was polite and offered a solution.', 7, 4, FALSE, NULL),
('INT016', 'Check Loan Application Status', 0.95, 'Hello, I want to know weeks.', 'Loan', NULL, 'Checked the application status using customer''s name.', 'pending', 'N/A', 'anxious, impatient', 'Neutral', 'Professional and helpful.', 8, 6, FALSE, NULL),
('INT017', 'KYC Information Request', 0.90, 'approved but we need urgently.', 'Loan', 'Customer unaware of KYC requirement: Lack of communication from the branch.', 'Explained KYC and promised to send required documents via SMS.', 'pending', 'N/A', 'confused, frustrated', 'Negative', 'Professional and apologetic.', 9, 7, FALSE, NULL),
('INT018', 'Fraudulent Charge Reporting', 0.95, 'Your bank so mass my credit, see the refund in 7 to 10 days.', 'Credit Card', 'Unauthorized charge of $15000: Customer claims they did not make the transaction.', 'Verified transaction details, blocked the card, and initiated a chargeback request.', 'resolved', 'Chargeback request initiated; refund expected in 7-10 days.', 'frustration, anger', 'Negative', 'The agent remained calm and professional despite the customer''s frustration.', 9, 6, FALSE, NULL),
('INT019', 'NEFT Transfer Setup', 0.95, 'Hey, I just open my anything else.', 'Savings Account, NEFT Transfer', NULL, 'Provided instructions on how to set up NEFT transfer, including beneficiary details and activation time.', 'resolved', 'The agent explained the steps to set up NEFT transfer via the app and informed the customer about the 24-hour activation period.', 'Excitement, Gratitude', 'Positive', 'The agent was polite, helpful, and clear in their instructions.', 9, 10, FALSE, NULL),
('INT020', 'Account Issue - Lean on Account', 0.95, 'I paid my loan ... what''s going on?', 'Loan, EMI', 'Lean on account after EMI payment: System error', 'Identified the issue, confirmed payment processing, and removed the lean.', 'resolved', 'Lean was lifted and funds are available.', 'frustration, concern', 'Negative', 'Professional and empathetic.', 9, 8, FALSE, NULL),
('INT021', 'Check credit limit increase status', 0.95, 'I requested a credit ... what''s the hold up?', 'Credit Card', 'Delay in processing credit limit increase request: Request is under review.', 'Checked the status of the request and expedited it.', 'pending', 'N/A', 'frustration, impatience', 'Negative', 'Agent was polite and helpful.', 8, 6, FALSE, NULL),
('INT022', 'Expedite credit limit increase', 0.90, 'Tomorrow can''t you ... a big purchase.', 'Credit Card', NULL, 'Prioritized the request and promised an update by end of day.', 'pending', 'N/A', 'urgency, anxiety', 'Neutral', 'Agent was accommodating and tried to meet customer''s needs.', 9, 7, FALSE, NULL),
('INT023', 'Fraudulent Transaction Report', 0.95, 'I am worried my and stealing my money.', 'Savings Account', 'Unauthorized withdrawal of $25000: Customer did not authorize the transaction.', 'Froze the customer''s account, filed a fraud report, and assured transaction reversal.', 'pending', 'Transaction will be reversed within 5 to 7 days.', 'worried, scared', 'Negative', 'Agent was reassuring and took appropriate actions.', 9, 7, FALSE, NULL),
('INT024', 'Car Loan Application Issue', 0.95, 'I tried applying for and the application today.', 'Car Loan', 'Online application portal error: System glitch or incorrect document format', 'Suggested uploading documents in PDF format or offered manual processing.', 'resolved', 'Agent offered to process the application manually after receiving documents via email.', 'frustration, confusion', 'Neutral', 'Professional and helpful.', 9, 8, FALSE, NULL),
('INT025', 'Account Closure', 0.95, 'I want to close delaying it', 'Savings Account', 'Delay in account closure: Branch is delaying the process, Pending balance: 500 rupees pending balance', 'Verified account, offered options for pending balance, initiated closure and transfer.', 'resolved', 'Account closure and balance transfer initiated; confirmation to be sent.', 'frustration, impatience', 'Negative', 'Professional and empathetic.', 9, 7, FALSE, NULL),
('INT026', 'Loan Preclosure', 0.95, 'I am thrilled my...do next?', 'Loan', NULL, 'Confirmed loan account number and provided payment instructions.', 'resolved', 'Payment link sent to customer for outstanding balance.', 'Happy, Excited', 'Positive', 'Professional and helpful.', 9, 9, TRUE, NULL),
('INT027', 'Debit Card Issue', 0.95, 'Hello, my debit card ... what''s the deal?', 'Debit Card', 'Debit card declined at store: Insufficient funds in the account.', 'Verified card activity, identified insufficient funds, and enabled online transactions.', 'resolved', 'Online transactions enabled.', 'frustration, surprise', 'Neutral', 'Professional and helpful.', 9, 7, FALSE, NULL),
('INT028', 'Address Update', 0.95, 'I went to the branch ... it''s not done yet.', 'Bank Account', 'Address update not processed: Missing signature on the form.', 'Agent apologized, checked the status, identified the issue, and offered to email the form and expedite the update.', 'pending', 'N/A', 'frustration, annoyance', 'Negative', 'Professional and helpful.', 8, 6, FALSE, NULL),
('INT029', 'Dispute late fee', 0.95, 'You guys are reaping me off...for your mistak.', 'Loan', 'Late fee charged despite on-time payment: ECS mandate issue caused payment to be credited late.', 'Verified payment, identified ECS issue, waived the late fee, and apologized.', 'resolved', 'Late fee waived; updated statement available in 24 hours.', 'anger, frustration', 'Negative', 'Agent remained calm and professional despite customer''s anger.', 9, 6, FALSE, NULL),
('INT030', 'Card Activation', 0.95, 'I''ve been trying to send it.', 'Credit Card', 'Card activation failed through automated process: Unknown processing error.', 'Verified customer details and manually activated the card.', 'resolved', 'Agent manually activated the customer''s credit card.', 'frustration, impatience', 'Negative', 'Agent remained professional despite customer''s impatience.', 10, 10, FALSE, NULL),
('INT031', 'Inquiry about charge', 0.95, 'Does a 200 rupees about?', 'Savings Account', 'Unexpected charge of 200 rupees: Maintenance fee due to low balance', 'Identified the charge, explained the reason, and waived the fee.', 'resolved', 'Fee waived as a one-time courtesy.', 'frustration, inquiry', 'Negative', 'Professional and helpful.', 9, 7, FALSE, NULL),
('INT032', 'Balance Alert Setup', 0.80, 'I waive the fee for you.', 'Savings Account', NULL, 'Offered to set up balance alerts.', 'pending', 'N/A', NULL, 'Neutral', 'Proactive and helpful.', 8, 6, FALSE, NULL),
('INT033', 'Loan Payment Assistance', 0.95, 'I am freaking out my...updated you are all', 'Loan', 'Unable to access account to make loan payment: Unknown reason for account access issue, Concern about impact on credit score due to potential late payment: Customer worried about CIBIL score.', 'Offered manual payment processing or extending the due date and processed manual payment.', 'resolved', 'Manual payment processed and account updated.', 'anxious, stressed, worried', 'Positive', 'The agent was helpful and reassuring.', 9, 9, FALSE, NULL),
('INT034', 'Fixed Deposit Withdrawal', 0.95, 'I want to withdraw ... how does that work?', 'Fixed Deposit', 'Premature withdrawal penalty: Customer wants to withdraw before maturity.', 'Agent offered to calculate the reduced interest amount.', 'pending', 'N/A', 'anxious, urgent', 'Neutral', 'Professional and helpful.', 8, 7, FALSE, NULL),
('INT035', 'Report unauthorized transaction', 0.95, 'I got a bill and what''s going on?', 'Credit Card', 'Unauthorized transaction of $8000: Customer did not make the transaction.', 'Verified last four digits of the card, pledged to freeze the card, and initiated a dispute.', 'pending', 'N/A', 'worried, concerned', 'Negative', 'The agent responded empathetically and took appropriate actions.', 8, 7, FALSE, NULL),
('INT036', 'Inquire about refund timeframe', 0.90, 'how long till and money back.', 'Credit Card', NULL, 'Provided an estimated refund timeframe of 5 to 7 days and promised to keep the customer updated.', 'pending', 'N/A', 'anxious', 'Neutral', 'The agent provided a clear timeframe and offered to keep the customer updated.', 9, 8, FALSE, NULL),
('INT037', 'Account Access Issue', 0.95, 'I tried checking my ... account not found help.', 'Loan Account, Online Portal', 'Customer cannot access loan balance online: Account not linked to the online portal.', 'Agent confirmed the account number and linked the account to the portal. Agent also offered to send login instructions and a guide, and provided further assistance if needed.', 'resolved', 'Account linked to the portal and login instructions sent.', 'frustration, confusion', 'Negative', 'Professional and helpful.', 9, 8, FALSE, NULL),
('INT038', 'Assistance Request', 0.85, 'Ok but I am ... will it be easy?', 'Online Portal, Loan Account', 'Customer is not comfortable with online processes: Lack of familiarity with online systems.', 'Agent assured the customer that the process is simple and offered a guide and further assistance.', 'resolved', 'Agent provided reassurance and offered a guide and further support.', 'anxiety, uncertainty', 'Neutral', 'Patient and reassuring.', 10, 9, FALSE, NULL),
('INT039', 'Track RTGS Transfer', 0.95, 'I setup RTGS transfers and them.', 'RTGS Transfer', NULL, 'Agent confirmed the transfer was completed and provided options to track it.', 'resolved', 'Agent confirmed transfer completion and offered tracking options.', 'positive, inquisitive', 'Positive', 'Professional and helpful.', 9, 10, FALSE, NULL),
('INT040', 'Request Statement', 0.90, 'I want to make sure statement.', 'Bank Statement', NULL, 'Agent offered to send a statement to the customer''s email.', 'resolved', 'Agent sent the statement to the customer''s email.', 'positive, grateful', 'Positive', 'Professional and helpful.', 9, 10, FALSE, NULL),
('INT041', 'Billing Dispute', 0.95, 'Hey, I''ve been charged ... happens this time.', 'Credit Card', 'Unauthorized subscription charge: System error', 'Initiated a chargeback request and promised updates.', 'pending', 'N/A', 'frustration, anger', 'Negative', 'Agent remained calm and empathetic despite customer''s frustration.', 8, 4, FALSE, NULL),
