('INT043', 'Check Loan Application Status', 0.95, 'Hello, I want to know weeks.', 'Loan', NULL, 'Checked the application status using customer''s name.', 'pending', 'N/A', 'anxious, impatient', 'Neutral', 'Professional and helpful.', 7, 4, FALSE, NULL),
('INT044', 'Escalation Request', 0.85, '48 hours can''t you ... business here.', 'Business Loan', 'Need for faster processing: Customer is losing business due to the delay.', 'Agent escalated the application for priority processing.', 'pending', 'N/A', 'frustration, urgency', 'Negative', 'Agent attempted to address the customer''s urgency.', 8, 6, FALSE, NULL),
